# -*- coding: utf-8 -*-
S = "полный обзор задач 11 класса и начало 9 класса (очередь G9–G11), проверено вычислением"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G9_TB_10_1", r"в условии написано «неравенство», хотя записано уравнение $x^{3/4}=27$; ключ верен: $x=27^{4/3}=81$",
  q=r"Решите уравнение $x^{\frac{3}{4}} = 27$.")
E("G9_TB_10_120", r"в ключе вместо $x=0{,}5$ стояло «$x=0$» и цепочки неравенств были неверными (например, $0{,}25<0{,}45<0{,}083$ ложно); значения: при $x=0{,}5$: $\frac1{12}<0{,}25<0{,}45$, при $x=1$: $\frac13<1<1{,}8$, при $x=2$: $\frac43<4<7{,}2$ (функции расположены по возрастанию коэффициента: $\frac13<1<1{,}8$)",
  k=r"при $x=0{,}5$: $\dfrac{1}{12}<0{,}25<0{,}45$; при $x=1$: $\dfrac{1}{3}<1<1{,}8$; при $x=2$: $\dfrac{4}{3}<4<7{,}2$",
  dnew={0: (r"при $x=0{,}5$: $0{,}45<0{,}25<\dfrac{1}{12}$; при $x=1$: $1{,}8<1<\dfrac{1}{3}$; при $x=2$: $7{,}2<4<\dfrac{4}{3}$", r"Ученик верно вычислил значения, но записал их в порядке убывания знаменателей-коэффициентов и поставил знаки «$<$» вместо «$>$»: на самом деле $\frac13x^{2}<x^{2}<1{,}8x^{2}$ при $x\ne0$."),
        1: (r"при $x=0{,}5$: $0{,}25<0{,}45<0{,}75$; при $x=1$: $1<1{,}8<3$; при $x=2$: $4<7{,}2<12$", r"Ученик прочитал коэффициент $\frac13$ как множитель $3$ и построил $y=3x^{2}$ вместо $y=\frac13x^{2}$."),
        2: (r"при $x=0{,}5$: $\dfrac{1}{12}<0{,}25<0{,}81$; при $x=1$: $\dfrac{1}{3}<1<3{,}24$; при $x=2$: $\dfrac{4}{3}<4<12{,}96$", r"Ученик возвёл в квадрат вместе с коэффициентом: $(1{,}8x)^{2}$ вместо $1{,}8\cdot x^{2}$; например, при $x=0{,}5$ получил $0{,}9^{2}=0{,}81$ вместо $0{,}45$.")})
